function home(){return `<section class="app-hero container"><div class="app-pitch"><div class="app-tag"><img src="/assets/eva-app-icon.svg" width="38" height="38" alt=""><span>EVA-3dScan <b>iPhone</b></span></div><div class="eyebrow">${s('campaign.heroEyebrow')}</div><h1>${s('hero.title')}</h1><p class="app-intro">${s('campaign.heroIntro')}</p><div class="button-row"><a class="button primary" href="#modules">${s('campaign.primary')} <span aria-hidden="true">â†˜</span></a>${link('/documentation','campaign.secondary','button secondary')}</div><div class="app-meta">${badge()}<span>iPhone + LiDAR*</span></div></div><div class="campaign-carousel" id="campaign-carousel" role="region" aria-roledescription="carousel" aria-label="${s('campaign.carouselLabel')}" tabindex="0">${campaignFrame()}<div class="carousel-bottom"><div class="carousel-dots">${[0,1,2,3,4].map(i=>`<button data-slide="${i}" aria-label="${s('campaign.slideLabel')} ${i+1}" aria-pressed="${i===campaignSlide}">${String(i+1).padStart(2,'0')}</button>`).join('')}</div><div class="carousel-controls"><button id="carousel-prev" aria-label="${s('campaign.previous')}">â†</button><button id="carousel-toggle" aria-label="${s(carouselPaused?'campaign.play':'campaign.pause')}">${carouselPaused?'â–¶':'â…¡'}</button><button id="carousel-next" aria-label="${s('campaign.next')}">â†’</button></div></div><div class="campaign-note">${s('campaign.campaignNote')}</div></div></section><section class="container module-equation" id="modules"><div class="equation-heading"><div><div class="eyebrow">1 + 1 + 1 = EVA-3dScan</div><h2>${s('campaign.moduleCount')}</h2></div><p>${s('campaign.heroMotto')}</p></div><div class="clear-modules">${[['objects','cube','objects'],['measure','ruler','live'],['spaces','room','spaces']].map(([r,ic,k],i)=>`<a class="clear-module module-${i+1}" data-route="/${r}" href="${url('/'+r)}"><div class="clear-module-top"><span>0${i+1}</span>${icon(ic)}</div><h3>${s('campaign.'+k+'Title')}</h3><p>${s('campaign.'+k+'Text')}</p><div class="module-output"><span>${s('modules.explore')}</span><b aria-hidden="true">â†—</b></div></a>`).join('')}</div></section><section class="flow-section"><div class="container"><div class="section-heading"><div><div class="eyebrow">${s('campaign.flowLabel')}</div><h2>${s('campaign.flowTitle')}</h2></div><p>${s('campaign.equation')}</p></div><div class="input-output">${[['input','focus'],['process','layers'],['output','cube']].map(([k,ic],i)=>`<article><span class="flow-symbol" aria-hidden="true">${i===0?'+':i===1?'â†’':'='}</span>${icon(ic)}<h3>${s('campaign.'+k+'Title')}</h3><p>${s('campaign.'+k+'Text')}</p></article>`).join('')}</div></div></section><section class="container audience-section"><div><div class="eyebrow">${s('campaign.audienceLabel')}</div><h2>${s('campaign.audienceTitle')}</h2></div><div class="audience-grid">${[['makers','cube'],['designers','focus'],['architects','room'],['interiors','ruler']].map(([key,ic])=>`<div>${icon(ic)}<span>${s('campaign.'+key)}</span></div>`).join('')}</div></section>${homeUses()}<section class="container app-compatibility"><span>*</span><p>${s('tech.captureText')}</p>${link('/technology','nav.technology','text-link')}</section>`;}
const campaignFiles=['06-architect','02-face','07-mario-walls','08-design-couple','09-repair-foreman'];
let campaignSlide=0,carouselPaused=matchMedia('(prefers-reduced-motion: reduce)').matches,carouselTimer=null,carouselHover=false,carouselExplicitPlay=false;
function campaignFrame(){const n=campaignSlide+1;return `<div class="campaign-frame" id="campaign-frame"><img src="/assets/campaign/${campaignFiles[campaignSlide]}.webp" width="1536" height="1024" alt="${s('campaign.slide'+n+'Alt')}" fetchpriority="${campaignSlide===0?'high':'auto'}"><div class="scan-sweep" aria-hidden="true"></div><span class="frame-index">${String(n).padStart(2,'0')} / 05</span>${campaignSlide===1?`<div class="speech-bubble">${s('campaign.speech')}</div>`:''}<div class="slide-caption"><h2>${s('campaign.slide'+n+'Title')}</h2><p>${s('campaign.slide'+n+'Text')}</p></div></div>`;}
function setCampaignSlide(index,{manual=false}={}){campaignSlide=(index+5)%5;if(manual){carouselPaused=true;carouselExplicitPlay=false;}const frame=document.getElementById('campaign-frame');if(!frame)return;frame.outerHTML=campaignFrame();document.querySelectorAll('[data-slide]').forEach((b,i)=>b.setAttribute('aria-pressed',String(i===campaignSlide)));const toggle=document.getElementById('carousel-toggle');toggle.textContent=carouselPaused?'â–¶':'â…¡';toggle.setAttribute('aria-label',t(carouselPaused?'campaign.play':'campaign.pause'));if(manual)document.getElementById('announcements').textContent=t('campaign.slide'+(campaignSlide+1)+'Title');scheduleCarousel();}
function scheduleCarousel(){clearTimeout(carouselTimer);if(route!=='/'||carouselPaused||document.hidden||(!carouselExplicitPlay&&(carouselHover||document.getElementById('campaign-carousel')?.contains(document.activeElement))))return;carouselTimer=setTimeout(()=>setCampaignSlide(campaignSlide+1),6500);}
document.addEventListener('click',event=>{const target=event.target.closest('button');if(!target)return;if(target.matches('[data-slide]'))setCampaignSlide(Number(target.dataset.slide),{manual:true});if(target.id==='carousel-prev')setCampaignSlide(campaignSlide-1,{manual:true});if(target.id==='carousel-next')setCampaignSlide(campaignSlide+1,{manual:true});if(target.id==='carousel-toggle'){carouselPaused=!carouselPaused;carouselExplicitPlay=!carouselPaused;target.textContent=carouselPaused?'â–¶':'â…¡';target.setAttribute('aria-label',t(carouselPaused?'campaign.play':'campaign.pause'));scheduleCarousel();}});
