function render({keepScroll=true}={}){const y=scrollY;const region=document.getElementById('campaign-carousel');const active=document.activeElement;const initialHydration=document.getElementById('app').dataset.ssr==='true';const useFocused=active?.id==='use-search';const useSelection=useFocused?[active.selectionStart,active.selectionEnd]:null;const focused=region?.contains(active);const focusSelector=useFocused?'#use-search':focused?(active.id?'#'+active.id:active.hasAttribute('data-slide')?'[data-slide="'+active.dataset.slide+'"]':null):null;if(region&&(carouselHover||region.matches(':hover')||focused))carouselPaused=true;const pages={'/':home,'/objects':objects,'/measure':measure,'/spaces':spaces,'/uses':uses,'/people':people,'/technology':technology,'/documentation':documentation,'/about':about};document.documentElement.lang=locale;document.title=(route==='/'?'':t(routeKeys[route]||'ui.notFound')+' Â· ')+t('meta.title');updatePageMetadata();document.getElementById('app').innerHTML=header()+`<main id="main" tabindex="-1">${pages[route]?pages[route]():`<section class="container page-heading"><h1>${s('ui.notFound')}</h1><p>${s('ui.notFoundText')}</p>${link('/','nav.home','button primary')}</section>`}</main>`+footer();document.getElementById('app').removeAttribute('data-ssr');if(keepScroll)window.scrollTo(0,y);carouselHover=false,carouselExplicitPlay=false;if(focusSelector)document.querySelector(focusSelector)?.focus({preventScroll:true});if(useSelection)document.getElementById('use-search')?.setSelectionRange(...useSelection);if(initialHydration&&location.hash){try{const id=decodeURIComponent(location.hash.slice(1));document.getElementById(id)?.scrollIntoView({block:'start',behavior:'instant'});}catch{}}scheduleCarousel();}
async function loadLanguage(next,{force=false}={}){next=normalize(next);requestedLocale=next;const id=++requestId;controller?.abort();controller=new AbortController();const old=locale;try{let data=cache.get(next);if(!data||force){const response=await fetch('/api/content?lang='+next,{signal:controller.signal,cache:'no-cache'});if(!response.ok)throw Error('Content '+response.status);data=await response.json();if(!data.messages||typeof data.messages!=='object')throw Error('Invalid content');cache.set(next,data);}if(id!==requestId)return;bundle=data;locale=next;storage.set(locale);const address=new URL(location.href);address.searchParams.set('lang',locale);history.replaceState({},'',address);render();document.getElementById('announcements').textContent=t('ui.updated');}catch(error){if(error.name==='AbortError')return;console.error('Content unavailable',error.message);if(bundle){locale=old;render();document.getElementById('announcements').textContent=t('ui.error');}else if(document.getElementById('app')?.dataset.ssr==='true'){document.getElementById('announcements').textContent='Content refresh unavailable';}else{const fallback={en:['Content is temporarily unavailable.','Try again'],ro:['ConÈ›inutul este temporar indisponibil.','ReÃ®ncearcÄƒ'],de:['Der Inhalt ist vorÃ¼bergehend nicht verfÃ¼gbar.','Erneut versuchen'],fr:['Le contenu est temporairement indisponible.','RÃ©essayer'],es:['El contenido no estÃ¡ disponible temporalmente.','Reintentar'],hu:['A tartalom Ã¡tmenetileg nem Ã©rhetÅ‘ el.','ÃšjraprÃ³bÃ¡lkozÃ¡s'],bg:['Ð¡ÑŠÐ´ÑŠÑ€Ð¶Ð°Ð½Ð¸ÐµÑ‚Ð¾ Ð²Ñ€ÐµÐ¼ÐµÐ½Ð½Ð¾ Ð½Ðµ Ðµ Ð´Ð¾ÑÑ‚ÑŠÐ¿Ð½Ð¾.','ÐžÐ¿Ð¸Ñ‚Ð°Ð¹Ñ‚Ðµ Ð¾Ñ‚Ð½Ð¾Ð²Ð¾']}[next];document.getElementById('app').innerHTML=`<div class="initial error-state"><img src="/assets/eva-mark-animated.svg" width="52" height="52" alt="EVA"><h1>${h(fallback[0])}</h1><button class="button primary" id="retry">${h(fallback[1])}</button></div>`;}}}
