function homeUses(){return `<section class="container home-uses"><div class="section-heading"><div><div class="eyebrow">${s('uses.homeLabel')}</div><h2>${s('uses.homeTitle')}</h2></div><p>${s('uses.homeText')}</p></div><div class="use-category-grid">${useCaseCategories.map(cat=>`<a class="use-category-card" href="${url('/uses')}" data-route="/uses" data-use-category="${cat}">${icon(categoryIcon[cat])}<h3>${s('uses.category.'+cat)}</h3><span aria-hidden="true">â†—</span></a>`).join('')}</div><div class="person-link"><p>${s('people.homeText')}</p>${link('/people','people.homeLink','text-link')}</div></section>`;}
