  function stage(){return `<div class="stage-context"><img src="/assets/campaign/${currentCase().module==='/people'&&mode==='object'?'02-face':scene[mode]}.webp" width="1536" height="1024" alt="${s(currentCase().module==='/people'&&mode==='object'?'campaign.slide2Alt':alt[mode])}" fetchpriority="high"><span>${s('status.concept')}</span></div><div class="phone-shell"><div class="phone-camera" aria-hidden="true"></div><div class="phone-top"><img src="/assets/eva-app-icon.svg" width="25" height="25" alt=""><strong>EVA-3dScan</strong>${icon('focus')}</div><div class="phone-title">${currentCase().module==='/people'&&mode==='object'?'3D':s('v2.'+(mode==='object'?'dimension':mode==='measure'?'wall':'connected'))}</div><div class="phone-viewport">${drawing()}<div class="phone-scanline" aria-hidden="true"></div></div><div class="phone-result"><span>${s('v2.preview')}</span><strong>${mode==='object'?(currentCase().module==='/people'?'3D':'100 × 100 × 100 mm'):mode==='measure'?'4.00 m':'3D → 2D'}</strong></div><div class="phone-bottom"><span class="capture-dot" aria-hidden="true"></span><span>${s('v2.demoLabel')}</span></div></div><div class="stage-chip">${icon(icons[mode])}<div><small>0${modes.indexOf(mode)+1} / 03</small><strong>${s(currentCase().module==='/people'&&mode==='object'?'usecase.'+problem+'.title':'v2.'+mode+'Result')}</strong></div></div>`;}
