 }
 results.languages.push(lang);
}
emit('customer-profile','maker');emit('customer-problem','portrait-keepsake');if(story.home().includes('value=\"portrait-keepsake\" selected'))results.errors.push('invalid out-of-profile accepted');
results.segmentKeyCounts=Object.fromEntries(Object.entries(segments).map(([k,v])=>[k,Object.keys(v).length]));
results.segmentEmpty=Object.values(segments).flatMap(v=>Object.values(v)).filter(v=>"'!v.trim()).length;
results.segmentInvalidSteps=Object.values(segments).flatMap(v=>Object.entries(v)).filter(([k,v])=>k.endsWith('"'Steps')&&v.split('|').length"'!==3).length;
